using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public sealed class CorpseCoordinationChecks:MonoBehaviour
{
 [Serializable]public class Result{public bool finished,passed;public string error;public List<string> checks=new List<string>();}public Result report=new Result();
 BedroomPhaseController p;BedroomEncounterDirector d;CorpseEncounterController c;NightEncounterSchedule[] oldSchedules;DoorEncounterConfig[] oldDoor;CorpseEncounterConfig oldConfig;InputSettings oldInput,testInput;Keyboard keyboard;Mouse mouse;
 void Check(bool value,string label){report.checks.Add((value?"PASS: ":"FAIL: ")+label);if(!value)throw new Exception(label);}
 void Key(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}IEnumerator Keys(params Key[] keys){Key(keys);yield return null;yield return null;}
 IEnumerator Wait(Func<bool> done,float timeout=12){float end=Time.realtimeSinceStartup+timeout;while(!done()&&Time.realtimeSinceStartup<end)yield return null;if(!done())throw new Exception("Timed out: corpse="+c.State+" door="+d.door.State+" phase="+p.State);}
 IEnumerator Aim(){p.CaptureCursor();for(int i=0;i<6;i++){var delta=c.head.position-p.view.transform.position;if(Vector3.Angle(p.view.transform.forward,delta)<1)break;var q=Quaternion.LookRotation(delta);InputSystem.QueueDeltaStateEvent(mouse.delta,new Vector2(Mathf.DeltaAngle(p.view.transform.eulerAngles.y,q.eulerAngles.y),-Mathf.DeltaAngle(p.view.transform.eulerAngles.x,q.eulerAngles.x))/p.movement.mouseSensitivity);yield return null;yield return null;}}
 IEnumerator Start(){p=FindAnyObjectByType<BedroomPhaseController>();d=p.corpse.director;c=p.corpse;d.automaticScheduling=false;d.quietInterval=.05f;oldSchedules=d.nightSchedules;d.nightSchedules=oldSchedules.Select(Instantiate).ToArray();oldDoor=d.door.nightConfigs;d.door.nightConfigs=oldDoor.Select(Instantiate).ToArray();oldConfig=c.config;c.config=Instantiate(oldConfig);c.config.initialDelay=0;c.config.beckoningSeconds=1.1f;c.config.reachingSeconds=5;c.config.resistanceSeconds=.4f;c.config.retreatSeconds=.2f;foreach(var s in d.nightSchedules){s.initialDelay=.05f;s.opportunityInterval=new Vector2(.1f,.1f);s.forceFirstEncounter=BedroomEncounterKind.None;s.underBedWeight=s.doorWeight=s.windowWeight=0;s.corpseWeight=1;}foreach(var config in d.door.nightConfigs){config.footstepsDuration=config.approachSilence=config.gentleDuration=config.aggressiveDuration=config.silenceAfterBanging=config.handleDuration=config.openingDuration=.1f;config.reactionGrace=.2f;config.listeningDuration=1.2f;config.retreatDuration=.2f;}
 oldInput=InputSystem.settings;testInput=Instantiate(oldInput);testInput.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;testInput.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=testInput;keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();
 var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){bool more=false;object next=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){report.error=ex.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested){stack.Push(nested);continue;}yield return next;}
 Key();InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);InputSystem.settings=oldInput;Destroy(testInput);foreach(var s in d.nightSchedules)Destroy(s);d.nightSchedules=oldSchedules;foreach(var s in d.door.nightConfigs)Destroy(s);d.door.nightConfigs=oldDoor;Destroy(c.config);c.config=oldConfig;report.finished=true;report.passed=string.IsNullOrEmpty(report.error);System.IO.File.WriteAllText("Temp/BedroomPrototype/Narrative/CoordinationChecks.json",JsonUtility.ToJson(report,true));Debug.Log("Corpse coordination checks: "+report.passed+" "+report.error);}
 IEnumerator Run(){yield return null;yield return null;p.introductions.debugAutoSkipAllIntroductions=true;p.introductions.DebugStartNight(3);p.night.nightDurationSeconds=300;d.underBed.SetEncountersEnabled(false);d.window.SetEncountersEnabled(false);d.door.SetEncountersEnabled(false);d.automaticScheduling=true;d.RestartAutomaticScheduling();yield return Wait(()=>c.State==CorpseEncounterState.Beckoning);Check(d.LastSelected==BedroomEncounterKind.Corpse&&d.SelectionCount>0,"existing director genuinely selects Night 3 corpse from its fourth weighted candidate");d.automaticScheduling=false;c.ResetEncounter();yield return new WaitForSeconds(.1f);
 d.door.SetEncountersEnabled(true);d.CurrentSchedule.corpseWeight=0;d.CurrentSchedule.doorWeight=1;d.CurrentSchedule.allowOverlappingWarnings=true;d.CurrentSchedule.maximumWarningConcurrency=2;Check(c.ForceStartEncounter(),"corpse warning starts before coordinated door encounter");d.automaticScheduling=true;d.RestartAutomaticScheduling();yield return Wait(()=>d.door.State==DoorMonsterState.Listening);d.automaticScheduling=false;yield return Keys(UnityEngine.InputSystem.Key.R);yield return new WaitForSeconds(.65f);Check(c.State==CorpseEncounterState.Beckoning&&c.StateElapsed>=c.config.beckoningSeconds,"corpse mandatory pull waits while door owns listening defense");Check(d.door.breath.IsHolding&&!c.BlocksOtherDefenses,"corpse warning does not interrupt R defense");yield return Wait(()=>d.door.State==DoorMonsterState.Retreat);yield return Keys();yield return Wait(()=>c.State==CorpseEncounterState.Reaching);Check(d.door.State==DoorMonsterState.Dormant&&d.door.SuccessfulDefenses>0,"door defense completes before corpse requires Q");Check(!d.TryBeginDefense(d.underBed),"corpse reservation excludes simultaneous mandatory blanket defense");yield return Aim();yield return Keys(UnityEngine.InputSystem.Key.Q);yield return Wait(()=>c.State==CorpseEncounterState.Retreat);yield return Keys();yield return Wait(()=>c.State==CorpseEncounterState.Dormant);Check(c.SuccessfulDefenses>0&&p.State==BedroomPhase.NightGameplay,"Q successfully counters corpse after coordinated door retreat");Check(d.SelectionBlockedReason(c).StartsWith("cooldown"),"director excludes corpse during its success cooldown");d.door.SetEncountersEnabled(false);d.window.panel.SetOpenAmount(1);yield return new WaitForSeconds(.1f);Check(p.nightExcursion.TryLeaveBed(),"existing window excursion remains available after fourth threat");yield return Wait(()=>p.NightStanding&&!p.IsTransitioning);Check(d.window.panel.TryClose(),"existing manual window close animation starts");Check(!c.ForceStartEncounter(),"corpse cannot begin lethal action during standing window interaction");yield return Wait(()=>!d.window.panel.IsAnimating);Check(!d.window.panel.IsWindowOpen&&d.window.DangerMultiplier==1,"manual closing preserves danger reset");Check(p.nightExcursion.TryReturnToBed(),"bed return remains available after coordinated encounters");yield return Wait(()=>p.CanUseNightActions);Check(p.night.Elapsed>0&&p.night.Running,"encounter coordination never resets or stops the running night clock");}
}
